<?php
declare(strict_types=1);
$root=dirname(__DIR__);$catalog=json_decode((string)file_get_contents($root.'/assets/ASSET-INVENTORY.json'),true,512,JSON_THROW_ON_ERROR);require_once $root.'/core/asset-registry.php';
