$seen=[];foreach(['javascript','css'] as $group){foreach($catalog[$group]??[] as $entry){$file=$entry['file']??'';if(isset($seen[$file]))throw new RuntimeException("Duplicate asset: {$file}");$seen[$file]=true;if(($expected[$file]??'')!==$group)throw new RuntimeException("Unknown inventory asset: {$file}");foreach(['owner','scope','callers','security_signals','security_review','purpose','registry_handle'] as $field)if(!array_key_exists($field,$entry))throw new RuntimeException("{$file} lacks {$field}");if(($entry['owner']??'')!=='cms')throw new RuntimeException("{$file} is not CMS-owned");if(snapsmack_asset_by_handle((string)$entry['registry_handle'])===null)throw new RuntimeException("{$file} has no working registry handle");if(!in_array($entry['scope']??'',['public','admin','tool'],true))throw new RuntimeException("{$file} has invalid scope");if(!is_array($entry['callers'])||$entry['callers']===[])throw new RuntimeException("{$file} lacks callers");if(in_array('CMS runtime',$entry['callers'],true))throw new RuntimeException("{$file} uses a placeholder instead of exact callers");if(($entry['security_signals']??[])!==[]&&(!is_array($entry['security_review']??null)||($entry['security_review']['signals']??null)!==$entry['security_signals']||trim((string)($entry['security_review']['review']??''))===''))throw new RuntimeException("{$file} has unreviewed security signals");}}
